import {districts} from './districts';
import {deepDistricts} from './districts/index';
import {destinations,categoryLabels} from './tourism/index.js';
import {historyPeriods,ancientPages,magadhaPages,mauryaPages,h5Pages,h6Pages,h7Pages,h8Pages} from './history';
import {personalities} from './catalog';
import {posts} from './blogs';
import {cultureSearchIndex} from './cultureSearch';
import {riverDirectory,naturalRegions,geographySystems} from './geography';
import {waterSearchRecords} from './geography/waterSystems';
import {ecologySearchRecords} from './geography/ecology';
import {agricultureSearchRecords} from './geography/agriculture';
import {economySearchRecords} from './economy';
import {societySearchRecords} from './society';
import {governanceSearchRecords} from './governance';
import {politicsSearchRecords} from './politics';
import {religionSearchRecords} from './religion/index.js';
import {personalitySearchRecords} from './personalities/directory.js';

const text=value=>Array.isArray(value)?value.filter(Boolean).join(' · '):String(value||'');
const normalized=value=>text(value).normalize('NFKD').toLocaleLowerCase('hi').replace(/[\u200c\u200d]/g,'').replace(/[^\p{L}\p{M}\p{N}]+/gu,' ').replace(/\s+/g,' ').trim();
const unique=items=>[...new Set(items.filter(Boolean))];
const entry=({id,title,to,type,aliases=[],keywords=[],description='',region=''})=>({id,title:text(title).trim(),to,type,aliases:unique(aliases.map(text)),keywords:unique(keywords.map(text)),description:text(description).trim(),region:text(region).trim()});

const deepPages=[...ancientPages,...magadhaPages,...mauryaPages,...h5Pages,...h6Pages,...h7Pages,...h8Pages];
const deepHistoryRoutes=new Set(deepPages.map(item=>`/history/${item.slug}`));
const districtAliases=new Map(deepDistricts.map(item=>[item.slug,item.aliases||[]]));
const historyEntries=[...deepPages.map(item=>entry({id:`history:${item.slug}`,title:item.shortTitle||item.title,to:`/history/${item.slug}`,type:'इतिहास',aliases:[item.title,item.englishTitle,...(item.aliases||[])],keywords:item.keywords||[],description:item.description,region:item.eyebrow})),...historyPeriods.filter(item=>!deepHistoryRoutes.has(item.route)).map(item=>entry({id:`history-period:${item.id}`,title:item.titleHindi,to:item.route||`/history#${item.id}`,type:'इतिहास',aliases:[item.titleEnglish,item.displayPeriod],keywords:[...(item.importantPeople||[]),...(item.importantPlaces||[]),...(item.keywords||[])],description:item.summary,region:item.displayPeriod}))];
const geographyEntries=[...riverDirectory.map(item=>entry({id:`river:${item.slug}`,title:item.nameHi,to:`/geography/rivers/${item.slug}`,type:'नदी',aliases:[item.nameEn,...(item.aliases||[])],keywords:item.districts||[],description:item.summary,region:item.riverSystem})),...naturalRegions.map(item=>entry({id:`natural-region:${item.slug}`,title:item.nameHi,to:`/geography/natural-regions/${item.slug}`,type:'प्राकृतिक क्षेत्र',aliases:[item.nameEn,item.type],keywords:item.districts||[],description:item.summary})),...Object.values(geographySystems).filter(item=>item.slug!=='natural-regions').map(item=>entry({id:`geography:${item.slug}`,title:item.nameHi,to:`/geography/${item.slug}`,type:'भूगोल',aliases:[item.nameEn],description:item.summary}))];
const genericEntries=(records,type)=>records.map(item=>entry({id:item.id||`${type}:${item.slug||item.name}`,title:item.name||item.nameHi||item.title,to:item.to||item.seo?.canonical,type:item.category||type,aliases:[item.nameEn,...(item.aliases||[])],keywords:item.tags||[],description:item.summary||item.description,region:item.region||item.district||item.districts}));
const rawSearchIndex=[...cultureSearchIndex.map(item=>entry({id:item.id,title:item.name,to:item.to,type:item.label,aliases:[item.nameEn,...item.aliases],keywords:[item.type,item.slug],description:'बिहार की संस्कृति, भाषा, पर्व या भोजन से जुड़ा संदर्भ।',region:item.regions||item.districts})),...districts.map(item=>entry({id:`district:${item.slug}`,title:item.nameHindi,to:`/district/${item.slug}`,type:'जिला',aliases:[item.nameEnglish,...(districtAliases.get(item.slug)||[])],keywords:item.famousFor||[],description:`${item.nameEnglish} · ${item.division} प्रमंडल`,region:item.division})),...destinations.map(item=>entry({id:`tourism:${item.slug}`,title:item.nameHi,to:`/tourism/${item.slug}`,type:'पर्यटन',aliases:[item.nameEn,...(item.aliases||[])],keywords:[item.district,...item.categories.map(category=>categoryLabels[category]||category)],description:item.summary,region:item.district})),...historyEntries,...geographyEntries,...genericEntries(waterSearchRecords,'जल तंत्र'),...genericEntries(ecologySearchRecords,'पारिस्थितिकी'),...genericEntries(agricultureSearchRecords,'कृषि'),...genericEntries(economySearchRecords,'अर्थव्यवस्था'),...genericEntries(societySearchRecords,'समाज'),...genericEntries(governanceSearchRecords,'शासन'),...personalities.map(item=>entry({id:`person:${item.slug}`,title:item.name,to:`/personalities/${item.slug}`,type:'व्यक्तित्व',aliases:item.aliases||[],keywords:[item.role],description:item.role})),...posts.map(item=>entry({id:`article:${item.slug}`,title:item.title,to:`/blog/${item.slug}`,type:'लेख',aliases:item.aliases||[],keywords:item.tags||[],description:item.excerpt,region:item.category}))];
const mergeEntries=items=>{const byRoute=new Map();for(const item of items){if(!item.title||!item.to)continue;const current=byRoute.get(item.to);if(!current){byRoute.set(item.to,item);continue;}byRoute.set(item.to,{...current,aliases:unique([...current.aliases,item.title,...item.aliases]),keywords:unique([...current.keywords,...item.keywords]),description:current.description||item.description});}return [...byRoute.values()];};
export const searchIndex=mergeEntries([...rawSearchIndex,...genericEntries(politicsSearchRecords,'राजनीति'),...genericEntries(religionSearchRecords,'धार्मिक विरासत'),...personalitySearchRecords.map(entry)]);
const scoreEntry=(item,query)=>{const title=normalized(item.title),aliases=item.aliases.map(normalized),keywords=item.keywords.map(normalized),description=normalized(item.description),region=normalized(item.region);if(title===query)return 1000;if(aliases.includes(query))return 940;if(title.startsWith(query))return 860;if(aliases.some(alias=>alias.startsWith(query)))return 800;const terms=query.split(' ').filter(Boolean),haystack=[title,...aliases,...keywords,region,description].join(' ');if(!terms.every(term=>haystack.includes(term)))return 0;const titleTerms=terms.filter(term=>title.includes(term)).length,aliasTerms=terms.filter(term=>aliases.some(alias=>alias.includes(term))).length,keywordTerms=terms.filter(term=>keywords.some(keyword=>keyword.includes(term))).length;return Math.min(799,400+(titleTerms*90)+(aliasTerms*70)+(keywordTerms*35)+(description.includes(query)?20:0));};
export const searchPortal=query=>{const normalizedQuery=normalized(query);if(!normalizedQuery)return [];const scored=searchIndex.map(item=>({...item,score:scoreEntry(item,normalizedQuery)})).filter(item=>item.score>0).sort((a,b)=>b.score-a.score||a.title.localeCompare(b.title,'hi'));const seenEntities=new Set();return scored.filter(item=>{const key=item.type+':'+normalized(item.title);if(seenEntities.has(key))return false;seenEntities.add(key);return true;}).slice(0,50);};
